import Moment from "moment";
import momentLocalizer from "react-widgets-moment";

Moment.locale("en");
momentLocalizer();

const tableIcons = {
  Add: forwardRef((props, ref) => <AddBox {...props} ref={ref} />),
  Check: forwardRef((props, ref) => <Check {...props} ref={ref} />),
  Clear: forwardRef((props, ref) => <Clear {...props} ref={ref} />),
  Delete: forwardRef((props, ref) => <DeleteOutline {...props} ref={ref} />),
  DetailPanel: forwardRef((props, ref) => (
    <ChevronRight {...props} ref={ref} />
  )),
  Edit: forwardRef((props, ref) => <Edit {...props} ref={ref} />),
  Export: forwardRef((props, ref) => <SaveAlt {...props} ref={ref} />),
  Filter: forwardRef((props, ref) => <FilterList {...props} ref={ref} />),
  FirstPage: forwardRef((props, ref) => <FirstPage {...props} ref={ref} />),
  LastPage: forwardRef((props, ref) => <LastPage {...props} ref={ref} />),
  NextPage: forwardRef((props, ref) => <ChevronRight {...props} ref={ref} />),
  PreviousPage: forwardRef((props, ref) => (
    <ChevronLeft {...props} ref={ref} />
  )),
  ResetSearch: forwardRef((props, ref) => <Clear {...props} ref={ref} />),
  Search: forwardRef((props, ref) => <Search {...props} ref={ref} />),
  SortArrow: forwardRef((props, ref) => <ArrowUpward {...props} ref={ref} />),
  ThirdStateCheck: forwardRef((props, ref) => <Remove {...props} ref={ref} />),
  ViewColumn: forwardRef((props, ref) => <ViewColumn {...props} ref={ref} />),
};

const useStyles = makeStyles({
  statusLabel: {
    width: "150px",
    display: "inline-block",
    textAlign: "center",
  },
});

const enrollSplitBtnStyle = {
  backgroundColor: "rgb(153, 46, 98)",
  color: "#fff",
  minWidth: 0,
  height: "2.2rem",
  lineHeight: 1,
  border: "none",
  boxShadow: "none",
  textTransform: "uppercase",
  fontFamily: "inherit",
  fontWeight: "bold",
  letterSpacing: "0.05em",
};

/**
 * The enrollment prompt runs on one blue, told apart by shade rather than hue
 * so the dialog reads as a single family. This is the LAMISPlus deep blue used
 * across the module, not the lighter toast blue (--prep-notify-blue in
 * css/toast-theme.css) — a toast is a transient strip, the dialog header is a
 * solid band behind white text and needs the stronger contrast.
 * Red is still reserved for the blocked-enrollment state.
 */
const BRAND_BLUE = "#014D88";
const BRAND_BLUE_LIGHT = "#0A6FB8";

const ENTRY_POINTS = [
  {
    code: ENROLLMENT_LABEL_PREP,
    label: ENROLLMENT_LABEL_PREP,
    title: "Pre-Exposure Prophylaxis",
    description:
      "Enroll a client at risk of HIV exposure into the PrEP service line.",
    accent: BRAND_BLUE,
  },
  {
    code: ENROLLMENT_LABEL_PEP,
    label: ENROLLMENT_LABEL_PEP,
    title: "Post-Exposure Prophylaxis",
    description:
      "Enroll a client following a recent potential HIV exposure into the PEP service line.",
    accent: BRAND_BLUE_LIGHT,
  },
];

const EntryPointCard = ({ entry, onSelect, disabled, disabledReason }) => {
  const accent = disabled ? "#9ca3af" : entry.accent;
  const card = (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      onClick={() => !disabled && onSelect(entry.code)}
      onKeyDown={(e) => {
        if (disabled) return;
        if (e.key === "Enter" || e.key === " ") onSelect(entry.code);
      }}
      style={{
        flex: "1 1 0",
        cursor: disabled ? "not-allowed" : "pointer",
        borderRadius: "0.5rem",
        border: `0.125rem solid ${accent}`,
        background: disabled ? "#f3f4f6" : "#fff",
        padding: "1.25rem 1rem",
        textAlign: "center",
        transition: "transform 0.12s ease, box-shadow 0.12s ease",
        outline: "none",
        opacity: disabled ? 0.7 : 1,
      }}
      onMouseEnter={(e) => {
        if (disabled) return;
        e.currentTarget.style.transform = "translateY(-0.125rem)";
        e.currentTarget.style.boxShadow = "0 0.5rem 1rem rgba(0,0,0,0.12)";
      }}
      onMouseLeave={(e) => {
        if (disabled) return;
        e.currentTarget.style.transform = "none";
        e.currentTarget.style.boxShadow = "none";
      }}
    >
      <div
        style={{
          width: "3rem",
          height: "3rem",
          borderRadius: "50%",
          background: accent,
          color: "#fff",
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: "0.75rem",
        }}
      >
        <Icon name="user plus" style={{ fontSize: "1.25rem", margin: 0 }} />
      </div>
      <div
        style={{
          fontSize: "1.1rem",
          fontWeight: 700,
          color: accent,
          marginBottom: "0.25rem",
        }}
      >
        {entry.label}
      </div>
      <div style={{ fontSize: "0.85rem", color: "#333", marginBottom: "0.5rem" }}>
        {entry.title}
      </div>
      <div style={{ fontSize: "0.75rem", color: "#666", lineHeight: 1.4 }}>
        {disabled && disabledReason ? disabledReason : entry.description}
      </div>
    </div>
  );
  if (disabled && disabledReason) {
    return (
      <Tooltip title={disabledReason} arrow>
        <div style={{ flex: "1 1 0", display: "flex" }}>{card}</div>
      </Tooltip>
    );
  }
  return card;
};

const EnrollPatientButton = ({ row }) => {
  const history = useHistory();
  const [open, setOpen] = useState(false);
  const [activeStatus, setActiveStatus] = useState({
    prep: false,
    pep: false,
    loaded: false,
  });
  const [loading, setLoading] = useState(false);
  // True only when the user clicked before the prefetch landed — drives the
  // button's transient "Checking…" state. Background prefetch never sets this,
  // so row buttons don't all flash a spinner while the list loads.
  const [awaitingOpen, setAwaitingOpen] = useState(false);
  // Open intent, read inside the fetch's async callback without stale closures.
  const openWhenLoadedRef = useRef(false);
  // Guards against duplicate in-flight requests (prefetch vs. an early click).
  const fetchingRef = useRef(false);

  // Resolve active-enrollment status from the backend. Cached after the first
  // success so the modal can open instantly in its final state — no jarring
  // spinner→content (or picker→active) switch inside the dialog.
  // Active-enrollment status is now shipped ON the grid row (computed server-side
  // by person_uuid), so we read it DIRECTLY — no round-trip. A client with an
  // active, not-yet-discontinued initiation on an arm is blocked there; a new
  // client (no initiation → both flags false/absent) can enroll.
  const fetchStatus = () => {
    if (activeStatus.loaded) return;
    setActiveStatus({
      prep: !!row?.isCurrentStatusInterruptedPrep,
      pep: !!row?.isCurrentStatusInterruptedPep,
      loaded: true,
    });
  };

  // Prefetch on mount so an active patient shows the red-orange blocked modal
  // the instant the user clicks — no visible state switch.
  useEffect(() => {
    fetchStatus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleOpen = () => {
    // Status is read synchronously from the row, so we can resolve + open in one
    // click (no async wait / "Checking…" state needed).
    fetchStatus();
    setOpen(true);
  };

  const blockedArm = activeStatus.prep
    ? "PrEP"
    : activeStatus.pep
    ? "PEP"
    : null;

  // PrEP minimum age is 15 — under-15 clients may only be enrolled into PEP.
  const ageNum = Number(row?.age);
  const prepBlockedByAge = Number.isFinite(ageNum) && ageNum < 15;
  // Backend flag: latest HTS encounter is early-detect with an antigen-only
  // or antigen + antibody reactive result. PrEP is contra-indicated; only
  // PEP may be initiated for these clients.
  const prepBlockedByEarlyDetect = !!row?.pepOnly;

  const handleEnroll = (screeningType) => {
    if (blockedArm) return; // hard-block; banner explains it
    if (screeningType === ENROLLMENT_LABEL_PREP
        && (prepBlockedByAge || prepBlockedByEarlyDetect)) return;
    setOpen(false);
    history.push({
      pathname: "/patient-dashboard",
      state: { patientObj: row, screeningType, freshEnroll: true },
    });
  };

  return (
    <>
      {/*
        Split-segment styling matching the Patient Dashboard button: a small icon
        on the left, a vertical divider, then the label on the right. Both
        segments share the same background; the divider is a translucent white
        rule so the seam is subtle.
      */}
      <MuiButton
        onClick={handleOpen}
        variant="contained"
        size="small"
        disableRipple
        disabled={awaitingOpen}
        style={{
          backgroundColor: "rgb(153, 46, 98)",
          color: "#fff",
          textTransform: "uppercase",
          fontFamily: "inherit",
          fontWeight: "bold",
          letterSpacing: "0.05em",
          fontSize: "0.8rem",
          padding: 0,
          height: "2.2rem",
          minWidth: 0,
          border: "none",
          boxShadow: "0 0.125rem 0.25rem rgba(0,0,0,0.2)",
          display: "inline-flex",
          alignItems: "stretch",
          overflow: "hidden",
        }}
      >
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            padding: "0 0.625rem",
            borderRight: "0.0625rem solid rgba(255,255,255,0.4)",
          }}
        >
          {awaitingOpen ? (
            <CircularProgress size={15} style={{ color: "#fff" }} />
          ) : (
            <Icon name="user plus" style={{ margin: 0, fontSize: "0.95rem" }} />
          )}
        </span>
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            padding: "0 1rem",
            whiteSpace: "nowrap",
          }}
        >
          {awaitingOpen ? "Checking…" : "Enroll Patient"}
        </span>
      </MuiButton>

      <Dialog
        open={open}
        onClose={() => setOpen(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{ style: { borderRadius: "0.5rem" } }}
      >
        <DialogTitle
          disableTypography
          style={{
            background:
              !activeStatus.loaded
                ? BRAND_BLUE
                : blockedArm
                ? "#F44336"
                : BRAND_BLUE,
            color: "#fff",
            padding: "0.75rem 1rem",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <span style={{ fontSize: "1rem", fontWeight: 600 }}>
            {!activeStatus.loaded
              ? "Loading…"
              : blockedArm
              ? "Active Enrollment"
              : "Select Enrollment Type"}
          </span>
          <IconButton
            size="small"
            onClick={() => setOpen(false)}
            style={{ color: "#fff" }}
          >
            <CloseIcon fontSize="small" />
          </IconButton>
        </DialogTitle>
        <DialogContent style={{ padding: "1.25rem" }}>
          {loading || !activeStatus.loaded ? (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: "0.75rem",
                padding: "1.5rem 0",
                color: "#555",
                fontSize: "0.9rem",
              }}
            >
              <CircularProgress size={20} />
              Checking enrollment status…
            </div>
          ) : (
            <>
              {/* One modal for both states: the two entry-point cards always
                  render. When the client is active on an arm we keep the cards
                  visible but disabled and surface a red-orange block notice
                  right below the header, instead of swapping to a separate
                  "Active Enrollment" view. */}
              {blockedArm ? (
                <div
                  role="alert"
                  style={{
                    marginBottom: "1rem",
                    fontSize: "0.95rem",
                    color: "#444",
                    lineHeight: 1.5,
                  }}
                >
                  <strong style={{ color: "#F44336" }}>
                    {row?.firstName} {row?.surname}
                  </strong>{" "}
                  is currently initiated for{" "}
                  <strong style={{ color: "#F44336" }}>{blockedArm}</strong>.
                  Discontinue this active enrollment before starting another!
                </div>
              ) : (
                <div
                  style={{
                    marginBottom: "1rem",
                    fontSize: "0.875rem",
                    color: "#444",
                  }}
                >
                  Choose the service line to enroll{" "}
                  <strong>
                    {row?.firstName} {row?.surname}
                  </strong>{" "}
                  into.
                </div>
              )}
              <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap" }}>
                {ENTRY_POINTS.map((entry) => {
                  const isPrepDisabledByAge =
                    entry.code === "PrEP" && prepBlockedByAge;
                  const isPrepDisabledByEarlyDetect =
                    entry.code === "PrEP" && prepBlockedByEarlyDetect;
                  const isPrepDisabled =
                    isPrepDisabledByAge || isPrepDisabledByEarlyDetect;
                  // Active enrollment hard-blocks BOTH arms; the PrEP-only
                  // age / early-detect rules still apply when not blocked.
                  const disabled = !!blockedArm || isPrepDisabled;
                  const disabledReason = blockedArm
                    ? `Client is currently active on ${blockedArm}. Discontinue it before enrolling.`
                    : isPrepDisabledByEarlyDetect
                    ? "Latest HTS encounter indicates a reactive antigen result — only PEP can be initiated."
                    : isPrepDisabledByAge
                    ? "Not available for clients under 15. Please use PEP."
                    : null;
                  return (
                    <EntryPointCard
                      key={entry.code}
                      entry={entry}
                      onSelect={handleEnroll}
                      disabled={disabled}
                      disabledReason={disabledReason}
                    />
                  );
                })}
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
};

const Patients = (props) => {
  const classes = useStyles();
  const [showPPI, setShowPPI] = useState(true);
  const startRequest = useLatestGridRequest();

  const handleCheckBox = (e) => {
    if (e.target.checked) {
      setShowPPI(false);
    } else {
      setShowPPI(true);
    }
  };

  return (
    <div>
      <MaterialTable
        icons={tableIcons}
        title="Find Patient"
        columns={[
          { title: "Patient Name", field: "name", hidden: showPPI },
          {
            title: "Hospital Number",
            field: "hospital_number",
            filtering: false,
          },
          { title: "Sex", field: "gender", filtering: false },
          { title: "Age", field: "age", filtering: false },
          { title: "Actions", field: "actions", filtering: false },
        ]}
        data={(query) =>
          new Promise((resolve, reject) => {
            const { signal, isCurrent } = startRequest();
            axios
              .get(
                `${baseUrl}prep/persons/hts?pageSize=${query.pageSize}&pageNo=${
                  query.page
                }&searchValue=${encodeURIComponent(query.search)}`,
                {
                  headers: { Authorization: `Bearer ${token}` },
                  timeout: 120000,
                  signal,
                }
              )
              .then((result) => {
                if (!isCurrent()) return;
                resolve({
                  data: result?.data?.records?.map?.((row) => ({
                    name: row.firstName + " " + row.surname,
                    hospital_number: row.hospitalNumber,
                    gender: row && row.gender ? row.gender : "",
                    age: row.age,
                    actions: <EnrollPatientButton row={row} />,
                  })) || [],
                  page: query.page,
                  totalCount: result?.data?.totalRecords || 0,
                });
              })
              .catch((error) => {
                if (isAbortError(error) || !isCurrent()) return;
                reject(error);
              });
          })
        }
        options={{
          headerStyle: {
            backgroundColor: "#014d88",
            color: "#fff",
          },
          searchFieldStyle: {
            width: "100%",
            margingLeft: "250px",
          },
          filtering: false,
          searchFieldAlignment: "left",
          pageSizeOptions: [10, 20, 100],
          pageSize: 10,
          debounceInterval: 400,
        }}
        components={{
          Toolbar: (props) => (
            <div className="p-2">
              <div className="form-check custom-checkbox float-left mt-4 ml-3">
                <input
                  type="checkbox"
                  className="form-check-input"
                  name="showPP!"
                  id="showPP"
                  value="showPP"
                  checked={showPPI === true ? false : true}
                  onChange={handleCheckBox}
                  style={{
                    border: "1px solid #014D88",
                    borderRadius: "0.25rem",
                  }}
                />
                <label className="form-check-label" htmlFor="basic_checkbox_1">
                  <b style={{ color: "#014d88", fontWeight: "bold" }}>
                    {" "}
                    SHOW PII{" "}
                  </b>
                </label>
              </div>
              <MTableToolbar {...props} />
            </div>
          ),
        }}
      />
    </div>
  );
};

export default Patients;
